import bisect
from collections import Counter
from typing import List, Tuple

import pandas as pd
from solver import Algorithm


class Evolved(Algorithm):
    """Bounded optimizer for character-Trie reuse using global and lexical layouts."""

    def __init__(self, df: pd.DataFrame = None):
        """Store the optional dataframe and initialize shape metadata."""
        self.df = df
        self.num_rows = 0
        self.num_cols = 0

    @staticmethod
    def _text(value) -> str:
        """Convert one cell to evaluator text, representing scalar missing values as empty."""
        try:
            missing = pd.isna(value)
            if isinstance(missing, bool) and missing:
                return ""
        except Exception:
            pass
        return str(value)

    @staticmethod
    def _lcp(left: str, right: str) -> int:
        """Return exact common-prefix length using binary-search string comparisons."""
        limit = min(len(left), len(right))
        if limit == 0 or left[0] != right[0]:
            return 0

        low, high = 1, limit
        while low < high:
            middle = (low + high + 1) // 2
            if left[:middle] == right[:middle]:
                low = middle
            else:
                high = middle - 1
        return low

    @classmethod
    def _reuse(cls, strings: List[str]) -> int:
        """Return exact character-Trie reuse from sorted adjacent-string LCPs."""
        if len(strings) < 2:
            return 0

        ordered = sorted(strings)
        total = 0
        previous = ordered[0]

        for current in ordered[1:]:
            if current == previous:
                total += len(current)
            else:
                total += cls._lcp(previous, current)
            previous = current

        return total

    @staticmethod
    def _merge(columns, order, col_merge):
        """Keep requested column groups contiguous without changing their values."""
        if not col_merge:
            return list(order)

        positions = {column: i for i, column in enumerate(order)}
        claimed = set()
        owners = {}

        for requested in col_merge:
            group = [
                column
                for column in order
                if column in requested and column not in claimed
            ]
            if not group:
                continue

            group.sort(key=positions.__getitem__)
            for column in group:
                owners[column] = group
                claimed.add(column)

        result = []
        emitted = set()

        for column in order:
            if column in emitted:
                continue

            group = owners.get(column)
            if group is None:
                result.append(column)
                emitted.add(column)
            else:
                result.extend(group)
                emitted.update(group)

        return result

    @classmethod
    def _normalize(cls, columns, integer_order, col_merge):
        """Convert an integer ordering into a complete merge-constrained permutation."""
        proposed = [columns[index] for index in integer_order]
        merged = cls._merge(columns, proposed, col_merge)
        lookup = {column: index for index, column in enumerate(columns)}
        return [lookup[column] for column in merged]

    @staticmethod
    def _serialize(text, orders):
        """Serialize each row using its own column permutation."""
        return [
            "".join(text[row][column] for column in orders[row])
            for row in range(len(orders))
        ]

    def _global_candidates(self, text, columns, col_merge):
        """Build global frequency-ranked and pair-frequency column orderings."""
        rows = len(text)
        width = len(columns)
        statistics = []

        for column in range(width):
            counts = Counter(text[row][column] for row in range(rows))
            repeated_mass = sum(
                len(value) * count * (count - 1)
                for value, count in counts.items()
            )
            statistics.append((repeated_mass, len(counts)))

        ranked = sorted(
            range(width),
            key=lambda column: (
                -statistics[column][0],
                statistics[column][1],
                column,
            ),
        )

        first = self._normalize(columns, ranked, col_merge)

        examined = ranked[:min(28, width)]
        pair_scores = []

        for left in examined:
            for right in examined:
                if left == right:
                    continue

                counts = Counter(
                    text[row][left] + text[row][right]
                    for row in range(rows)
                )
                score = sum(
                    len(value) * count * (count - 1)
                    for value, count in counts.items()
                )
                if score:
                    pair_scores.append((-score, left, right))

        pair_scores.sort()
        used = set()
        paired = []

        for _, left, right in pair_scores:
            if left in used or right in used:
                continue
            paired.extend((left, right))
            used.add(left)
            used.add(right)

        paired.extend(column for column in ranked if column not in used)
        second = self._normalize(columns, paired, col_merge)

        return [first, second], ranked

    def _prototype_candidate(self, text, columns, col_merge, base_order):
        """Use lexical-quantile anchors and bracket-local greedy layouts on representative rows."""
        rows = len(text)
        width = len(columns)
        fallback = self._normalize(columns, base_order, col_merge)
        result = [fallback[:] for _ in range(rows)]

        if rows < 2 or width < 2:
            return result

        active = base_order[:min(24, width)]

        def make_string(row, order):
            """Serialize one row through an integer column ordering."""
            return "".join(text[row][column] for column in order)

        # Serialize the whole collection in the stable global layout so that
        # lexical neighborhoods are based on all rows, not input adjacency.
        lexical = sorted(
            (make_string(row, base_order), row)
            for row in range(rows)
        )

        anchor_count = min(12, len(lexical))
        anchor_positions = [
            (index * (len(lexical) - 1)) // max(1, anchor_count - 1)
            for index in range(anchor_count)
        ]
        anchors = [lexical[position][0] for position in anchor_positions]

        # Choose representative rows from lexical quantiles.  This avoids the
        # previous input-prefix bias while retaining the hard 256-row bound.
        sample_count = min(256, rows)
        if rows <= sample_count:
            sample_rows = [row for _, row in lexical]
        else:
            sample_positions = [
                (index * (len(lexical) - 1)) // max(1, sample_count - 1)
                for index in range(sample_count)
            ]
            sample_rows = [lexical[position][1] for position in sample_positions]

        def nearest_anchor(value):
            """Choose the better LCP match among the two bracketing anchors."""
            position = bisect.bisect_left(anchors, value)

            if position <= 0:
                return 0
            if position >= len(anchors):
                return len(anchors) - 1

            left = position - 1
            right = position
            left_score = self._lcp(value, anchors[left])
            right_score = self._lcp(value, anchors[right])

            if right_score > left_score:
                return right
            return left

        for row in sample_rows:
            value = make_string(row, base_order)
            prototype = anchors[nearest_anchor(value)]

            remaining = list(active)
            chosen = []
            cursor = 0

            while remaining:
                best_column = remaining[0]
                best_score = -1

                for column in remaining:
                    score = self._lcp(
                        text[row][column],
                        prototype[cursor:],
                    )
                    if score > best_score:
                        best_score = score
                        best_column = column

                chosen.append(best_column)
                cursor += len(text[row][best_column])
                remaining.remove(best_column)

            tail = [
                column for column in base_order
                if column not in chosen
            ]
            result[row] = self._normalize(
                columns,
                chosen + tail,
                col_merge,
            )

        return result

    def reorder(
        self,
        df: pd.DataFrame,
        early_stop: int = 0,
        row_stop: int = None,
        col_stop: int = None,
        col_merge=[],
        one_way_dep=[],
        distinct_value_threshold=0.8,
        parallel=True,
    ) -> Tuple[pd.DataFrame, List[List[str]]]:
        """Select the highest exact-reuse bounded layout and return reordered data."""
        self.df = df
        self.num_rows, self.num_cols = df.shape

        rows, width = df.shape
        columns = list(df.columns)

        if rows == 0 or width == 0:
            return df.copy(), [[] for _ in range(rows)]

        raw = df.to_numpy(dtype=object, copy=True)
        text = [
            [self._text(raw[row, column]) for column in range(width)]
            for row in range(rows)
        ]

        global_candidates, base_order = self._global_candidates(
            text,
            columns,
            col_merge,
        )

        candidates = []

        for order in global_candidates:
            orders = [order[:] for _ in range(rows)]
            serialized = self._serialize(text, orders)
            candidates.append((
                self._reuse(serialized),
                orders,
                serialized,
            ))

        lexical_orders = self._prototype_candidate(
            text,
            columns,
            col_merge,
            base_order,
        )
        lexical_serialized = self._serialize(text, lexical_orders)
        candidates.append((
            self._reuse(lexical_serialized),
            lexical_orders,
            lexical_serialized,
        ))

        _, best_orders, best_serialized = max(
            candidates,
            key=lambda item: item[0],
        )

        row_order = sorted(
            range(rows),
            key=lambda row: best_serialized[row],
        )

        output = [
            [raw[row, column] for column in best_orders[row]]
            for row in row_order
        ]
        orderings = [
            [columns[column] for column in best_orders[row]]
            for row in row_order
        ]

        result = pd.DataFrame(
            output,
            columns=columns,
            index=df.index.take(row_order),
            dtype=object,
        )
        return result, orderings
